'use strict';
// Terrain is cached; upright objects share a ground-contact depth with creatures.
function spriteGround(anchor,size){return anchor+(58/64-.72)*size;}
function scenerySize(t){return t.obj===2?2.8:t.obj===11?1.8:t.obj===3?1.4:2.25;}
function worldDepthItems(minX,maxX,minY,maxY){const items=[];for(let y=minY;y<maxY;y++)for(let x=minX;x<maxX;x++){const t=grid[idx(x,y)];if(t.obj>=0)items.push({type:'object',x,y,t,depth:spriteGround(y+.65,scenerySize(t))});if(t.ore?.amount>0)items.push({type:'ore',x,y,t,depth:spriteGround(y+.5,1.65)});}for(const h of houses)if(h.x>=minX-2&&h.x<maxX+2&&h.y>=minY-2&&h.y<maxY+2)items.push({type:'house',h,depth:spriteGround(h.y,3.6+h.level*.4)});for(const b of buildings)if(b.x>=minX-2&&b.x<maxX+2&&b.y>=minY-2&&b.y<maxY+2)items.push({type:'building',b,depth:spriteGround(b.y,3.8)});for(const e of entities)if(!isResidentIndoors(e)&&e.x>=minX-2&&e.x<maxX+2&&e.y>=minY-2&&e.y<maxY+2)items.push({type:'creature',e,depth:spriteGround(e.y,e.kind==='human'?1.55:e.kind==='wolf'?1.6:1.7)});return items.sort((a,b)=>a.depth-b.depth);}
function paintDepthWorld(minX,maxX,minY,maxY){for(const item of worldDepthItems(minX,maxX,minY,maxY)){if(item.type==='object'){const {x,y,t}=item,sway=typeof animatedScenery==='function'&&animatedScenery(x,y,t);ctx.save();if(sway){ctx.translate(x+.5,y+.65);ctx.rotate(Math.sin(animationTime()*1.3+idx(x,y))*.025);ctx.translate(-x-.5,-y-.65);}if(!(typeof paintBiomeObject==='function'&&paintBiomeObject(ctx,x,y,t)))drawSprite(t.obj,x+.5,y+.65,t.obj===2?2.8:t.obj===11?1.8:t.obj===3?1.4:2.25);ctx.restore();}else if(item.type==='ore')drawEconomySprite(oreSprites[item.t.ore.type],item.x+.5,item.y+.5,1.65);else if(item.type==='house'){const h=item.h;drawSprite(8+h.level,h.x,h.y,3.6+h.level*.4);}else if(item.type==='building'){const b=item.b;drawEconomySprite(buildingDefs[b.kind].sprite,b.x,b.y,3.8);}else{const e=item.e;ctx.fillStyle='#092a3660';ctx.beginPath();ctx.ellipse(e.x,e.y+.4,.36,.16,0,0,7);ctx.fill();drawCreature(e,creatureBob(e));if(e.hp<65){ctx.fillStyle='#5d302d';ctx.fillRect(e.x-.5,e.y-1,.9,.12);ctx.fillStyle='#a4e4a4';ctx.fillRect(e.x-.5,e.y-1,.9*e.hp/100,.12);}if(e.id===selectedId){ctx.strokeStyle='#fff2b8';ctx.lineWidth=.1;ctx.beginPath();ctx.arc(e.x,e.y,.85,0,7);ctx.stroke();}}}}
function animalObstacles(e,x,y){if(e.kind==='human'||e.sailing)return[];const body=['mammoth','triceratops','stego'].includes(e.species)?.32:.20,result=[];for(let yy=Math.max(0,Math.floor(y)-1);yy<Math.min(H,Math.floor(y)+2);yy++)for(let xx=Math.max(0,Math.floor(x)-1);xx<Math.min(W,Math.floor(x)+2);xx++)if([0,1,2].includes(grid[idx(xx,yy)].obj))result.push({x:xx+.5,y:yy+.65,r:body+.18});for(const h of houses)if(h.hp>0&&Math.abs(h.x-x)<2&&Math.abs(h.y-y)<2)result.push({x:h.x,y:h.y,r:body+.65});for(const b of buildings)if(Math.abs(b.x-x)<2&&Math.abs(b.y-y)<2)result.push({x:b.x,y:b.y,r:body+.65});return result;}
function animalPositionClear(e,x,y){return animalObstacles(e,x,y).every(o=>Math.hypot(x-o.x,y-o.y)>=o.r);}
const depthAdvance=advanceCreature;
advanceCreature=function(e,dt){if(e.kind==='human'||e.sailing){depthAdvance(e,dt);return;}const m=motionFor(e);for(const o of animalObstacles(e,e.x,e.y)){const dx=e.x-o.x,dy=e.y-o.y,d=Math.hypot(dx,dy);if(d<o.r+.35&&d>.01){const nx=dx/d,ny=dy/d,toward=m.vx*nx+m.vy*ny;if(toward<0){const side=(e.id%2?1:-1),push=(o.r+.35-d)*dt*8;m.vx+=nx*push-ny*push*side;m.vy+=ny*push+nx*push*side;}}}depthAdvance(e,dt);for(const o of animalObstacles(e,e.x,e.y)){const dx=e.x-o.x,dy=e.y-o.y,d=Math.hypot(dx,dy);if(d<o.r){const angle=d>.01?Math.atan2(dy,dx):e.id*2.4,x=o.x+Math.cos(angle)*(o.r+.015),y=o.y+Math.sin(angle)*(o.r+.015);if(walkable(x,y)){e.x=x;e.y=y;}}}};
mapDirty=true;

// Local steering keeps the shared terrain routes inexpensive.
const objectNavigate=navigate;
navigate=function(e){const ok=objectNavigate(e);if(e.kind==='human'||e.sailing||!ok)return ok;const dx=e.tx-e.x,dy=e.ty-e.y,length=Math.hypot(dx,dy);if(length<.05)return ok;const ux=dx/length,uy=dy/length,seen=new Set();let blocker=null;
for(let distance=.25;distance<=Math.min(length,3);distance+=.4){for(const o of animalObstacles(e,e.x+ux*distance,e.y+uy*distance)){const key=o.x+':'+o.y;if(seen.has(key))continue;seen.add(key);const along=(o.x-e.x)*ux+(o.y-e.y)*uy,across=Math.abs((o.x-e.x)*uy-(o.y-e.y)*ux);if(along>-.15&&along<length+.1&&across<o.r+.08&&(!blocker||along<blocker.along))blocker={...o,along};}}
if(!blocker)return ok;const m=mindFor(e);m.detourSide??=e.id%2?1:-1;for(const side of [m.detourSide,-m.detourSide]){const r=blocker.r+.35,x=blocker.x-uy*r*side+ux*.45,y=blocker.y+ux*r*side+uy*.45;if(walkable(x,y)&&animalPositionClear(e,x,y)&&clearRoute(e,{x,y})){e.tx=x;e.ty=y;m.detourSide=side;return true;}}return ok;};
